import hashlib, json, re
from pathlib import Path
import numpy as np

root = Path(".")
model_path = root/"model/tiny_mlp_mfcc92_edge_robust.npz"
m = np.load(model_path, allow_pickle=True)
names = [str(x) for x in m["LABEL_NAMES"].tolist()]

def fmt_float(v): return f"{float(v):.9e}f"
def c_array(name, arr, dims=""):
    arr = arr.astype(np.float32)
    if arr.ndim == 2:
        rows = ["    { " + ", ".join(fmt_float(v) for v in row) + " }" for row in arr]
        return f"static const float {name}{dims} = {{\\n" + ",\\n".join(rows) + "\\n};\\n"
    return f"static const float {name}{dims} = {{ " + ", ".join(fmt_float(v) for v in arr.ravel()) + " };\\n"

fd, hd, nc = m["W1"].shape[0], m["W1"].shape[1], len(names)
float_text = f"""#ifndef MODEL_WEIGHTS_H
#define MODEL_WEIGHTS_H

#define FEATURE_DIM {fd}
#define HIDDEN_DIM {hd}
#define NUM_CLASSES {nc}

"""
for name,dims in [("W1","[FEATURE_DIM][HIDDEN_DIM]"),("B1","[HIDDEN_DIM]"),("W2","[HIDDEN_DIM][NUM_CLASSES]"),("B2","[NUM_CLASSES]"),("FEATURE_MEAN","[FEATURE_DIM]"),("FEATURE_STD","[FEATURE_DIM]")]:
    float_text += c_array(name,m[name],dims)
float_text += 'static const char *LABEL_NAMES[NUM_CLASSES] __attribute__((unused)) = { ' + ", ".join(f'"{n}"' for n in names) + " };\\n\\n#endif\\n"

def quant(a):
    ma=float(np.max(np.abs(a)))
    if ma < 1e-10: ma=1e-10
    s=ma/127
    return np.round(a/s).astype(np.int8),s
def i8arr(name,a,dims=""):
    if a.ndim==2:
        return f"static const int8_t {name}{dims} = {{\\n" + ",\\n".join("    { "+", ".join(str(int(v)) for v in row)+" }" for row in a) + "\\n};\\n"
    return f"static const int8_t {name}{dims} = {{ " + ", ".join(str(int(v)) for v in a.ravel()) + " };\\n"
def farr(name,a,dims=""):
    return f"static const float {name}{dims} = {{ " + ", ".join(f"{float(v):.9e}f" for v in a.ravel()) + " };\\n"
qs={n:quant(m[n]) for n in ("W1","B1","W2","B2")}
int8_text=f"""#ifndef MODEL_WEIGHTS_INT8_H
#define MODEL_WEIGHTS_INT8_H

#include <stdint.h>

#define FEATURE_DIM {fd}
#define HIDDEN_DIM {hd}
#define NUM_CLASSES {nc}

"""
for n,d in [("W1","[FEATURE_DIM][HIDDEN_DIM]"),("B1","[HIDDEN_DIM]"),("W2","[HIDDEN_DIM][NUM_CLASSES]"),("B2","[NUM_CLASSES]")]:
    int8_text += i8arr(n+"_INT8",qs[n][0],d)+farr(n+"_SCALE",np.array([qs[n][1]]))
int8_text += farr("FEATURE_MEAN",m["FEATURE_MEAN"],"[FEATURE_DIM]")+farr("FEATURE_STD",m["FEATURE_STD"],"[FEATURE_DIM]")
int8_text += 'static const char *LABEL_NAMES[NUM_CLASSES] __attribute__((unused)) = { ' + ", ".join(f'"{n}"' for n in names) + " };\\n\\n#endif\\n"

for label,text,path in [("float",float_text,root/"app/audiodetect/model_weights.h"),("int8",int8_text,root/"app/audiodetect/model_weights_int8.h")]:
    actual=path.read_text()
    print(f"{label}_header_exact_match={actual==text}")
    print(f"{label}_expected_sha256={hashlib.sha256(text.encode()).hexdigest()}")
    print(f"{label}_actual_sha256={hashlib.sha256(actual.encode()).hexdigest()}")

param_count=sum(m[k].size for k in ("W1","B1","W2","B2"))
float_bytes=sum(m[k].nbytes for k in ("W1","B1","W2","B2","FEATURE_MEAN","FEATURE_STD"))
int8_bytes=sum(qs[k][0].nbytes for k in qs)+16+m["FEATURE_MEAN"].nbytes+m["FEATURE_STD"].nbytes
print(f"shapes W1={m['W1'].shape} B1={m['B1'].shape} W2={m['W2'].shape} B2={m['B2'].shape}")
print(f"parameters={param_count} float_bytes={float_bytes} int8_bytes={int8_bytes} reduction={(1-int8_bytes/float_bytes)*100:.6f}%")

x=json.loads((root/"results/python_cv/metrics_extended.json").read_text())
errors=[]
for cond, paths in x["conditions"].items():
  for mode, d in paths.items():
    cm=np.asarray(d["confusion_matrix"],dtype=int)
    overall=float(np.trace(cm)/cm.sum())
    recalls=np.diag(cm)/cm.sum(axis=1)
    macro=float(recalls.mean())
    if abs(overall-d["overall_accuracy"])>1e-12: errors.append((cond,mode,"overall"))
    if abs(macro-d["macro_recall"])>1e-12: errors.append((cond,mode,"macro"))
    for i,n in enumerate(names):
      pc=d["per_class"][n]
      prec=cm[i,i]/cm[:,i].sum() if cm[:,i].sum() else 0
      rec=recalls[i]
      f1=2*prec*rec/(prec+rec) if prec+rec else 0
      vals=[pc["support"],pc["correct"],pc["precision"],pc["recall"],pc["f1"]]
      exp=[int(cm[i].sum()),int(cm[i,i]),prec,rec,f1]
      if any(abs(float(a)-float(b))>1e-12 for a,b in zip(vals,exp)): errors.append((cond,mode,n))
    print(f"{cond:8} {mode:5} overall={overall*100:.5f}% macro={macro*100:.5f}% recalls="+",".join(f"{v*100:.2f}" for v in recalls))
print("metric_recalculation_errors=",errors)

raw=json.loads((root/"results/python_cv/metrics.json").read_text())
# Compare shared condition summaries and matrices.
raw_by={c["name"]:c for c in raw["aggregate"]}
map_names={"clean":"clean","snr_20db":"snr_20db","snr_10db":"snr_10db","snr_5db":"snr_5db"}
mismatch=[]
for ext_name,raw_name in map_names.items():
  rr=raw_by[raw_name]
  for mode in ("float","int8"):
    ed=x["conditions"][ext_name][mode]
    rd=rr[mode]
    for ek,rk in [("overall_accuracy","overall"),("macro_recall","macro"),("confusion_matrix","confusion_matrix")]:
      if ed[ek]!=rd[rk]: mismatch.append((ext_name,mode,ek))
print("metrics_json_vs_extended_mismatches=",mismatch)
