     1	/*
     2	 * INT8 quantized model inference.
     3	 *
     4	 * Weights are stored as int8 with per-tensor scale factors.
     5	 * During inference, each weight is dequantized on-the-fly:
     6	 *   float_weight = (float)int8_weight * scale
     7	 *
     8	 * This reduces model storage by ~75% (4x compression) with
     9	 * negligible accuracy loss (<0.5% typically).
    10	 *
    11	 * Drop-in replacement for model_infer.c — just change the include
    12	 * and call model_predict_int8() instead of model_predict().
    13	 */
    14	#include "model_infer_int8.h"
    15	#include <math.h>
    16	
    17	int model_predict_int8(const float features[FEATURE_DIM], float probabilities[NUM_CLASSES])
    18	{
    19	    float hidden[HIDDEN_DIM];
    20	    float logits[NUM_CLASSES];
    21	    float max_logit;
    22	    float sum_exp = 0.0f;
    23	    int i;
    24	    int j;
    25	
    26	    /* Layer 1: FEATURE_DIM -> HIDDEN_DIM with ReLU */
    27	    for (j = 0; j < HIDDEN_DIM; ++j) {
    28	        float acc = (float)B1_INT8[j] * B1_SCALE;  /* dequantize bias */
    29	        for (i = 0; i < FEATURE_DIM; ++i) {
    30	            float std = FEATURE_STD[i] == 0.0f ? 1.0f : FEATURE_STD[i];
    31	            float x = (features[i] - FEATURE_MEAN[i]) / std;
    32	            /* dequantize weight on-the-fly */
    33	            float w = (float)W1_INT8[i][j] * W1_SCALE;
    34	            acc += x * w;
    35	        }
    36	        hidden[j] = acc > 0.0f ? acc : 0.0f;  /* ReLU */
    37	    }
    38	
    39	    /* Layer 2: HIDDEN_DIM -> NUM_CLASSES */
    40	    for (j = 0; j < NUM_CLASSES; ++j) {
    41	        float acc = (float)B2_INT8[j] * B2_SCALE;  /* dequantize bias */
    42	        for (i = 0; i < HIDDEN_DIM; ++i) {
    43	            float w = (float)W2_INT8[i][j] * W2_SCALE;  /* dequantize weight */
    44	            acc += hidden[i] * w;
    45	        }
    46	        logits[j] = acc;
    47	    }
    48	
    49	    /* Softmax */
    50	    max_logit = logits[0];
    51	    for (j = 1; j < NUM_CLASSES; ++j) {
    52	        if (logits[j] > max_logit) {
    53	            max_logit = logits[j];
    54	        }
    55	    }
    56	    for (j = 0; j < NUM_CLASSES; ++j) {
    57	        probabilities[j] = expf(logits[j] - max_logit);
    58	        sum_exp += probabilities[j];
    59	    }
    60	    for (j = 0; j < NUM_CLASSES; ++j) {
    61	        probabilities[j] /= sum_exp;
    62	    }
    63	
    64	    /* Return argmax */
    65	    j = 0;
    66	    for (i = 1; i < NUM_CLASSES; ++i) {
    67	        if (probabilities[i] > probabilities[j]) {
    68	            j = i;
    69	        }
    70	    }
    71	    return j;
    72	}
