    92	static void set_auto_start_preference(bool enabled)
    93	{
    94	  FILE *file = fopen(AED_AUTOSTART_PATH, "w");
    95	  if (file != NULL)
    96	    {
    97	      fputs(enabled ? "1\n" : "0\n", file);
    98	      fclose(file);
    99	    }
   100	}
   101	
   102	static bool get_auto_start_preference(void)
   103	{
   104	  char value = '1';
   105	  FILE *file = fopen(AED_AUTOSTART_PATH, "r");
   106	  if (file != NULL)
   107	    {
   108	      if (fread(&value, 1, 1, file) != 1)
   109	        {
   110	          value = '1';
   111	        }
   112	
   113	      fclose(file);
   114	    }
   115	
   116	  return value != '0';
   117	}
   118	
   119	static void set_phase(enum aed_phase_e phase, const char *error)
   120	{
   121	  pthread_mutex_lock(&g_state.lock);
   122	  g_state.phase = phase;
   123	  if (error != NULL)
   124	    {
   125	      snprintf(g_state.error, sizeof(g_state.error), "%s", error);
   126	    }
   127	  else
   128	    {
   129	      g_state.error[0] = '\0';
   130	    }
   131	
   132	  g_state.revision++;
   133	  pthread_mutex_unlock(&g_state.lock);
   134	}
   135	
   136	static void save_result(const aed_result_t *result)
   137	{
   138	  pthread_mutex_lock(&g_state.lock);
   139	  g_state.result = *result;
   140	  g_state.segment_count++;
   141	  if (result->class_index != 0 && result->confidence >= 0.80f)
   142	    {
   143	      int i;
   144	      for (i = AED_HISTORY_SIZE - 1; i > 0; i--)
   145	        {
   146	          memcpy(g_state.history[i], g_state.history[i - 1],
   147	                 sizeof(g_state.history[i]));
   148	        }
   149	
   150	      g_state.event_count++;
   151	      snprintf(g_state.history[0], sizeof(g_state.history[0]),
   152	               "#%lu  %-12s  %3.0f%%",
   153	               (unsigned long)g_state.segment_count,
   154	               g_class_names[result->class_index],
   155	               result->confidence * 100.0f);
   156	    }
   157	
   158	  g_state.phase = g_state.enabled ? AED_PHASE_RECORDING : AED_PHASE_IDLE;
   159	  g_state.revision++;
   160	  pthread_mutex_unlock(&g_state.lock);
   161	}
   162	
   163	static void *capture_worker(void *arg)
   164	{
   165	  (void)arg;
   166	
   167	  system("amixer set 25 1");
   168	  system("amixer set 17 1");
   169	
   170	  for (;;)
   171	    {
   172	      bool enabled;
   173	      aed_result_t result;
   174	
   175	      pthread_mutex_lock(&g_state.lock);
   176	      enabled = g_state.enabled;
   177	      pthread_mutex_unlock(&g_state.lock);
   178	
   179	      if (!enabled)
   180	        {
   181	          set_phase(AED_PHASE_IDLE, NULL);
   182	          usleep(100000);
   183	          continue;
   184	        }
   185	
   186	      set_phase(AED_PHASE_RECORDING, NULL);
   187	      if (system(AED_CAPTURE_COMMAND) != 0)
   188	        {
   189	          set_phase(AED_PHASE_ERROR, "Microphone capture failed");
   190	          sleep(1);
   191	          continue;
   192	        }
   193	
   194	      set_phase(AED_PHASE_ANALYZING, NULL);
   195	      if (aed_classify_three_second_wav(AED_CAPTURE_PATH, &result) < 0)
   196	        {
   197	          set_phase(AED_PHASE_ERROR, "Audio analysis failed");
   198	          sleep(1);
   199	          continue;
   200	        }
   201	
   202	      save_result(&result);
   203	    }
   204	
   205	  return NULL;
   206	}
