   381	static void refresh_ui(lv_timer_t *timer)
   382	{
   383	  struct aed_snapshot_s snapshot;
   384	  uint32_t status_color = 0x637381;
   385	  uint32_t result_color;
   386	  const char *status_text = "READY";
   387	  int confidence;
   388	
   389	  (void)timer;
   390	  pthread_mutex_lock(&g_state.lock);
   391	  snapshot.enabled = g_state.enabled;
   392	  snapshot.auto_start = g_state.auto_start;
   393	  snapshot.phase = g_state.phase;
   394	  snapshot.segment_count = g_state.segment_count;
   395	  snapshot.event_count = g_state.event_count;
   396	  snapshot.result = g_state.result;
   397	  memcpy(snapshot.error, g_state.error, sizeof(snapshot.error));
   398	  memcpy(snapshot.history, g_state.history, sizeof(snapshot.history));
   399	  pthread_mutex_unlock(&g_state.lock);
   400	
   401	  if (snapshot.phase == AED_PHASE_RECORDING)
   402	    {
   403	      status_text = snapshot.enabled ? "LISTENING - CAPTURING 3S"
   404	                                     : "STOPPING CURRENT WINDOW";
   405	      status_color = 0x0b8f78;
   406	    }
   407	  else if (snapshot.phase == AED_PHASE_ANALYZING)
   408	    {
   409	      status_text = "ANALYZING";
   410	      status_color = 0x2a6fbb;
   411	    }
   412	  else if (snapshot.phase == AED_PHASE_ERROR)
   413	    {
   414	      status_text = snapshot.error[0] ? snapshot.error : "AUDIO ERROR";
   415	      status_color = 0xd54848;
   416	    }
   417	  else if (!snapshot.enabled)
   418	    {
   419	      status_text = "PAUSED";
   420	    }
   421	
   422	  lv_label_set_text(g_widgets.status_label, status_text);
   423	  lv_obj_set_style_text_color(g_widgets.status_label,
   424	                              lv_color_hex(status_color), 0);
   425	  lv_obj_set_style_bg_color(g_widgets.status_dot,
   426	                            lv_color_hex(status_color), 0);
   427	
   428	  result_color = g_class_colors[snapshot.result.class_index];
   429	  lv_label_set_text(g_widgets.result_label,
   430	                    g_class_names[snapshot.result.class_index]);
   431	  lv_obj_set_style_text_color(g_widgets.result_label,
   432	                              lv_color_hex(result_color), 0);
   433	
   434	  confidence = (int)(snapshot.result.confidence * 100.0f + 0.5f);
   435	  lv_label_set_text_fmt(g_widgets.confidence_label, "Confidence  %d%%",
   436	                        confidence);
   437	  lv_bar_set_value(g_widgets.confidence_bar, confidence, LV_ANIM_ON);
   438	  lv_obj_set_style_bg_color(g_widgets.confidence_bar,
   439	                            lv_color_hex(result_color), LV_PART_INDICATOR);
   440	  lv_label_set_text_fmt(g_widgets.energy_label, "Energy  %.6f",
   441	                        snapshot.result.energy);
   442	
   443	  if (snapshot.enabled)
   444	    {
   445	      lv_obj_add_state(g_widgets.start_button, LV_STATE_DISABLED);
   446	      lv_obj_clear_state(g_widgets.stop_button, LV_STATE_DISABLED);
   447	    }
   448	  else
   449	    {
   450	      lv_obj_clear_state(g_widgets.start_button, LV_STATE_DISABLED);
   451	      lv_obj_add_state(g_widgets.stop_button, LV_STATE_DISABLED);
   452	    }
   453	
   454	  if (snapshot.auto_start)
   455	    {
   456	      lv_obj_add_state(g_widgets.auto_switch, LV_STATE_CHECKED);
   457	    }
   458	  else
   459	    {
   460	      lv_obj_clear_state(g_widgets.auto_switch, LV_STATE_CHECKED);
   461	    }
   462	
   463	  lv_label_set_text_fmt(g_widgets.segment_label, "Windows %lu",
   464	                        (unsigned long)snapshot.segment_count);
   465	  lv_label_set_text_fmt(g_widgets.event_label, "Alerts %lu",
   466	                        (unsigned long)snapshot.event_count);
   467	}
