   469	int audiodetect_ui_main(int argc, char *argv[])
   470	{
   471	  lv_nuttx_dsc_t info;
   472	  lv_nuttx_result_t result;
   473	  pthread_attr_t attributes;
   474	  pthread_t worker;
   475	  int attempt;
   476	
   477	  (void)argc;
   478	  (void)argv;
   479	
   480	  if (lv_is_initialized())
   481	    {
   482	      fprintf(stderr, "Audio UI is already running\n");
   483	      return 1;
   484	    }
   485	
   486	  g_state.auto_start = get_auto_start_preference();
   487	  g_state.enabled = g_state.auto_start;
   488	  g_state.phase = g_state.enabled ? AED_PHASE_RECORDING : AED_PHASE_IDLE;
   489	  snprintf(g_state.history[0], sizeof(g_state.history[0]), "--");
   490	  snprintf(g_state.history[1], sizeof(g_state.history[1]), "--");
   491	  snprintf(g_state.history[2], sizeof(g_state.history[2]), "--");
   492	
   493	  lv_init();
   494	  for (attempt = 1; attempt <= AED_DISPLAY_INIT_ATTEMPTS; attempt++)
   495	    {
   496	      lv_nuttx_dsc_init(&info);
   497	#ifdef CONFIG_LV_USE_NUTTX_LCD
   498	      info.fb_path = "/dev/lcd0";
   499	#else
   500	      info.fb_path = "/dev/fb0";
   501	#endif
   502	      info.input_path = CONFIG_AE_AUDIODETECT_UI_INPUT_DEVPATH;
   503	      lv_nuttx_init(&info, &result);
   504	      if (result.disp != NULL && result.indev != NULL)
   505	        {
   506	          break;
   507	        }
   508	
   509	      fprintf(stderr,
   510	              "Audio UI hardware init failed (%d/%d): display=%p input=%p\n",
   511	              attempt, AED_DISPLAY_INIT_ATTEMPTS, result.disp, result.indev);
   512	      lv_nuttx_deinit(&result);
   513	
   514	      if (attempt < AED_DISPLAY_INIT_ATTEMPTS)
   515	        {
   516	          lv_deinit();
   517	          sleep(AED_DISPLAY_INIT_RETRY_SECONDS);
   518	          lv_init();
   519	        }
   520	    }
   521	
   522	  if (result.disp == NULL || result.indev == NULL)
   523	    {
   524	      fprintf(stderr, "Audio UI hardware did not become ready\n");
   525	      lv_deinit();
   526	      return 1;
   527	    }
   528	
   529	#ifndef CONFIG_LV_USE_NUTTX_LCD
   530	  lv_display_set_rotation(result.disp, LV_DISPLAY_ROTATION_180);
   531	#endif
   532	
   533	  build_ui();
   534	  lv_timer_create(refresh_ui, 200, NULL);
   535	  refresh_ui(NULL);
   536	
   537	  pthread_attr_init(&attributes);
   538	  pthread_attr_setstacksize(&attributes, 65536);
   539	  if (pthread_create(&worker, &attributes, capture_worker, NULL) != 0)
   540	    {
