    64	def _mel_filterbank(num_filters: int, nfft: int, sample_rate: int) -> np.ndarray:
    65	    """Pre-compute Mel filter bank matrix."""
    66	    high_freq = sample_rate / 2
    67	    mel_min = _hz_to_mel(0)
    68	    mel_max = _hz_to_mel(high_freq)
    69	    mel_points = np.linspace(mel_min, mel_max, num_filters + 2)
    70	    hz_points = np.array([_mel_to_hz(m) for m in mel_points])
    71	    bin_points = np.floor((nfft + 1) * hz_points / sample_rate).astype(int)
    72	
    73	    fbank = np.zeros((num_filters, nfft // 2 + 1), dtype=np.float32)
    74	    for m in range(1, num_filters + 1):
    75	        left = bin_points[m - 1]
    76	        center = bin_points[m]
    77	        right = bin_points[m + 1]
    78	        for k in range(left, center):
    79	            if center > left:
    80	                fbank[m - 1, k] = (k - left) / (center - left)
    81	        for k in range(center, right):
    82	            if right > center:
