   104	def extract_mfcc(pcm: np.ndarray, sample_rate: int = SAMPLE_RATE) -> np.ndarray:
   105	    """Extract MFCC features from PCM audio.
   106	
   107	    Args:
   108	        pcm: int16 mono audio samples
