   110	
   111	    Returns:
   112	        MFCC matrix of shape (num_frames, NUM_MFCC)
   113	    """
   114	    if sample_rate != SAMPLE_RATE:
   115	        raise ValueError(f"Expected {SAMPLE_RATE}Hz, got {sample_rate}Hz")
   116	
   117	    # Normalize to float
   118	    x = pcm.astype(np.float32) / 32768.0
   119	
   120	    # Pre-emphasis filter (high-pass): y[n] = x[n] - 0.97 * x[n-1]
   121	    x = np.append(x[0], x[1:] - 0.97 * x[:-1])
