   128	        end = min(start + FRAME_LEN, len(x))
   129	        frames[i, :end - start] = x[start:end]
   130	
   131	    # Apply Hamming window
   132	    hamming = 0.54 - 0.46 * np.cos(2 * np.pi * np.arange(FRAME_LEN) / (FRAME_LEN - 1))
   133	    frames *= hamming
   134	
   135	    # FFT (magnitude spectrum)
   136	    fft_result = np.fft.rfft(frames, n=NFFT, axis=1)
