   131	/* ---- In-place radix-2 FFT (N must be power of 2) ---- */
   132	
   133	static void fft_radix2(float *real, float *imag, int n)
   134	{
   135	    /* Bit reversal permutation */
   136	    int j = 0;
   137	    for (int i = 1; i < n; i++) {
   138	        int bit = n >> 1;
   139	        while (j & bit) {
   140	            j ^= bit;
   141	            bit >>= 1;
   142	        }
   143	        j ^= bit;
   144	        if (i < j) {
   145	            float tr = real[i]; real[i] = real[j]; real[j] = tr;
   146	            float ti = imag[i]; imag[i] = imag[j]; imag[j] = ti;
   147	        }
   148	    }
   149	
   150	    /* Cooley-Tukey */
   151	    for (int len = 2; len <= n; len <<= 1) {
   152	        float angle = -2.0f * M_PI / len;
   153	        float wr = cosf(angle), wi = sinf(angle);
   154	        for (int i = 0; i < n; i += len) {
   155	            float wmr = 1.0f, wmi = 0.0f;
   156	            for (int k = 0; k < len / 2; k++) {
   157	                float tr = wmr * real[i + k + len/2] - wmi * imag[i + k + len/2];
   158	                float ti = wmr * imag[i + k + len/2] + wmi * real[i + k + len/2];
   159	                real[i + k + len/2] = real[i + k] - tr;
   160	                imag[i + k + len/2] = imag[i + k] - ti;
   161	                real[i + k] += tr;
   162	                imag[i + k] += ti;
   163	                float nwr = wmr * wr - wmi * wi;
   164	                wmi = wmr * wi + wmi * wr;
   165	                wmr = nwr;
   166	            }
   167	        }
   168	    }
   169	}
